WITH scored AS (SELECT *, AVG(balance) OVER (PARTITION BY account_type ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS balance_avg_2, FIRST_VALUE(balance) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_balance, AVG(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS balance_avg_2_prior, LAG(balance, 2, 0) OVER (ORDER BY opened_date, id) AS prev_balance FROM accounts) SELECT id, customer_id, account_type, opened_date, balance_avg_2, first_known_balance, prev_balance FROM scored ORDER BY id DESC;
